<?php
namespace App\Core;
final class Auth { public static function user(): ?array { return $_SESSION['user'] ?? null; } public static function attempt(string $email,string $password): bool { $s=Database::pdo()->prepare('select * from users where email=? and status="active"'); $s->execute([$email]); $u=$s->fetch(); if($u && password_verify($password,$u['password'])){ session_regenerate_id(true); $_SESSION['user']=$u; return true; } return false; } public static function require(string $role): void { $u=self::user(); if(!$u || ($role!=='auth' && $u['role']!==$role && $u['role']!=='admin')){ header('Location: /login'); exit; } } public static function logout(): void { unset($_SESSION['user']); } public static function apiUser(string $token): ?array { $s=Database::pdo()->prepare('select u.* from api_tokens t join users u on u.id=t.user_id where t.token_hash=? and t.expires_at>now()'); $s->execute([hash('sha256',$token)]); return $s->fetch() ?: null; } }
